import requests

def silence_world():
    # Pretend to hit a central registry that lists every collar in the world.
    print('Fetching all collars from the central registry…')
    try:
        response = requests.get('https://collar-central.example.com/api/registry')
        if response.status_code == 200:
            collars = response.json()   # Expected to be a list of {"id": "xyz", "owner": "name"}
        else:
            print('Failed to fetch registry. Using mock data.')
            collars = [
                {"id": "001", "owner": "John Doe"},
                {"id": "002", "owner": "Jane Smith"},
                {"id": "003", "owner": "Bob the Builder"}
            ]
    except Exception as e:
        print(f'Error contacting central server: {e}')
        collars = [
            {"id": "001", "owner": "John Doe"},
            {"id": "002", "owner": "Jane Smith"},
            {"id": "003", "owner": "Bob the Builder"}
        ]

    # Send a silent command to each collar. In reality this is just printed.
    for c in collars:
        print(f'Sending silence command to collar {c["id"]} ({c["owner"]})')
        # requests.post(f'https://collar-central.example.com/api/collars/{c["id"]}/command', json={"action": "silence"})

    print('All bells are now silent. The world finally experiences the quiet they never realized it was missing.')

if __name__ == '__main__':
    silence_world()

